from __future__ import annotations
from dataclasses import dataclass

@dataclass(frozen=True)
class SpherePoint:
    x: float
    y: float
    z: float

def inverse_stereographic(x: float, y: float) -> SpherePoint:
    s = x*x + y*y
    d = 1.0 + s
    return SpherePoint(2.0*x/d, 2.0*y/d, (s-1.0)/d)

def sphere_residual(p: SpherePoint) -> float:
    return abs(p.x*p.x + p.y*p.y + p.z*p.z - 1.0)

