from __future__ import annotations
from pathlib import Path
W, H, M = 900, 520, 60
rs = [10.0*i/300.0 for i in range(301)]
def x_mode(r: float) -> float: return 2.0*r/(1.0+r*r)
def z_mode(r: float) -> float: return (r*r-1.0)/(1.0+r*r)
def sx(r: float) -> float: return M+r/10.0*(W-2*M)
def sy(v: float) -> float: return H-M-(v+1.0)/2.0*(H-2*M)
def path(fn): return " ".join(("M" if i==0 else "L")+f"{sx(r):.2f},{sy(fn(r)):.2f}" for i,r in enumerate(rs))
